@DatabaseRepositoryAdapter public class MybatisMfaAuthenticationRepository implements MfaMethodRepository,RecoveryCodeRepository{private final IamAuthenticationDao dao;public MybatisMfaAuthenticationRepository(IamAuthenticationDao dao){this.dao=dao;}public Optional<MfaMethod>findActive(CredentialSubjectType t,String id){return Optional.ofNullable(dao.findActiveMfa(t.name(),id)).map(this::method);}public Optional<MfaMethod>findById(String id){return Optional.ofNullable(dao.findMfaById(id)).map(this::method);}public List<MfaMethod>findAll(CredentialSubjectType t,String id){return dao.findAllMfa(t.name(),id).stream().map(this::method).toList();}public MfaMethod save(MfaMethod m,long expected){int n=expected==0?dao.insertMfa(row(m)):dao.updateMfa(row(m),expected);if(n!=1)throw new IamOptimisticLockException("MfaMethod",m.methodId(),expected);return m;}public void replace(CredentialSubjectType t,String id,List<RecoveryCode>codes){dao.deleteRecoveryCodes(t.name(),id);for(RecoveryCode c:codes)dao.insertRecoveryCode(row(c));}public List<RecoveryCode>findUnused(CredentialSubjectType t,String id){return dao.findUnusedRecoveryCodes(t.name(),id).stream().map(this::code).toList();}public boolean markUsed(String id,Instant at){return dao.markRecoveryCodeUsed(id,at);}private MfaMethod method(Map<String,Object>r){Instant verified=instant(r,"verifiedAt");return MfaMethod.reconstitute(string(r,"methodId"),CredentialSubjectType.valueOf(string(r,"subjectType")),string(r,"subjectId"),MfaMethod.Type.valueOf(string(r,"methodType")),MfaMethod.Status.valueOf(string(r,"status")),string(r,"protectedSecret"),string(r,"keyId"),intValue(r,"digits"),intValue(r,"periodSeconds"),string(r,"algorithm"),instant(r,"enrolledAt"),Optional.ofNullable(verified),longValue(r,"version"));}private RecoveryCode code(Map<String,Object>r){return new RecoveryCode(string(r,"recoveryCodeId"),CredentialSubjectType.valueOf(string(r,"subjectType")),string(r,"subjectId"),string(r,"codeHash"),instant(r,"createdAt"),Optional.ofNullable(instant(r,"usedAt")));}private Map<String,Object>row(MfaMethod m){Map<String,Object>r=new HashMap<>();r.put("methodId",m.methodId());r.put("subjectType",m.subjectType().name());r.put("subjectId",m.subjectId());r.put("methodType",m.type().name());r.put("status",m.status().name());r.put("protectedSecret",m.protectedSecret());r.put("keyId",m.keyId());r.put("digits",m.digits());r.put("periodSeconds",m.periodSeconds());r.put("algorithm",m.algorithm());r.put("enrolledAt",m.enrolledAt());r.put("verifiedAt",m.verifiedAt().orElse(null));r.put("version",m.version());return r;}private Map<String,Object>row(RecoveryCode c){Map<String,Object>r=new HashMap<>();r.put("recoveryCodeId",c.recoveryCodeId());r.put("subjectType",c.subjectType().name());r.put("subjectId",c.subjectId());r.put("codeHash",c.codeHash());r.put("createdAt",c.createdAt());r.put("usedAt",c.usedAt().orElse(null));return r;}}
